-- Create a new database
CREATE DATABASE imdb;

-- Switch to the new database for subsequent SQL commands
USE imdb;


CREATE TABLE mytable(
   director_name             VARCHAR(18) NOT NULL 
  ,duration                  INTEGER 
  ,director_facebook_likes   INTEGER  NOT NULL
  ,actor_3_facebook_likes    INTEGER 
  ,actor_2_name              VARCHAR(20) NOT NULL
  ,actor_1_facebook_likes    INTEGER  NOT NULL
  ,gross                     INTEGER 
  ,genres                    VARCHAR(57) NOT NULL
  ,actor_1_name              VARCHAR(20) NOT NULL
  ,movie_title               VARCHAR(55) NOT NULL
  ,cast_total_facebook_likes INTEGER  NOT NULL
  ,actor_3_name              VARCHAR(20)
  ,plot_keywords             VARCHAR(95)
  ,country                   VARCHAR(11)
  ,content_rating            VARCHAR(5)
  ,budget                    INTEGER 
  ,title_year                INTEGER 
  ,actor_2_facebook_likes    INTEGER  NOT NULL
  ,imdb_score                NUMERIC(3,1) NOT NULL
  ,movie_facebook_likes      INTEGER  NOT NULL
);

